const execution = $json.execution || {};
const applicationRecordedNodes = new Set([
  'Run and Persist Bounded Research',
  'Generate Evaluate and Persist Posts',
  'Reevaluate and Persist Readiness',
  'Direct Generate Validate Compose and Persist',
  'Persist Selective Content Action',
]);
const raw = String(execution.error?.message || $json.trigger?.error?.message || '').toLowerCase();
const transportFailure = /gateway|inactivity|timeout|timed out|econn|socket|network|connection reset/.test(raw);
if (applicationRecordedNodes.has(String(execution.lastNodeExecuted || '')) && !transportFailure) {
  return [{ json: { persist: false, reason: 'application_failure_already_recorded' } }];
}
return $input.all().map((item) => ({ json: { ...item.json, persist: true } }));

const crypto = require('crypto');
const execution = $json.execution || {};
const workflow = $json.workflow || {};
const raw = String(execution.error?.message || $json.trigger?.error?.message || '').toLowerCase();
let errorCode = 'workflow_execution_failed';
let category = 'permanent';
let retryable = false;
if (/rate.?limit|429/.test(raw)) { errorCode = 'provider_rate_limit'; category = 'provider'; retryable = true; }
else if (/timeout|timed out/.test(raw)) { errorCode = 'provider_timeout'; category = 'provider'; retryable = true; }
else if (/network|connection|unavailable|econn/.test(raw)) { errorCode = 'dependency_unavailable'; category = 'transient'; retryable = true; }
else if (/signature|nonce|auth|forbidden|permission/.test(raw)) { errorCode = 'workflow_security_rejection'; category = 'security'; }
else if (/budget|quota|cost/.test(raw)) { errorCode = 'workflow_budget_rejection'; category = 'budget'; }
else if (/validation|schema|invalid|malformed/.test(raw)) { errorCode = 'workflow_validation_rejection'; category = 'validation'; }
const workflowExecutionId = String(execution.id || '');
if (!workflowExecutionId) throw new Error('Failed execution ID is unavailable');
const path = '/api/internal/workflows/recovery/failures';
const payload = {
  contractVersion: '1.0',
  workflowExecutionId,
  retryOfExecutionId: execution.retryOf ? String(execution.retryOf) : null,
  workflowName: String(workflow.name || 'Unknown workflow').slice(0, 160),
  errorCode,
  category,
  retryable,
  occurredAt: new Date().toISOString(),
};
const body = JSON.stringify(payload);
const timestamp = String(Math.floor(Date.now() / 1000));
const nonce = crypto.randomUUID();
const digest = crypto.createHash('sha256').update(body, 'utf8').digest('hex');
const canonical = [timestamp, nonce, 'POST', path, digest].join('\n');
const secret = $env.WORKFLOW_HMAC_SECRET;
const baseUrl = $env.APP_BASE_URL;
if (!secret || !baseUrl) throw new Error('Recovery workflow environment is not configured');
const signature = `sha256=${crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex')}`;
return [{ json: { body, nonce, signature, timestamp, url: `${baseUrl}${path}` } }];

const crypto = require('crypto');
const path = '/api/internal/workflows/recovery/dispatch';
const payload = { contractVersion: '1.0', requestedAt: new Date().toISOString(), limit: 5 };
const body = JSON.stringify(payload);
const timestamp = String(Math.floor(Date.now() / 1000));
const nonce = crypto.randomUUID();
const digest = crypto.createHash('sha256').update(body, 'utf8').digest('hex');
const canonical = [timestamp, nonce, 'POST', path, digest].join('\n');
const secret = $env.WORKFLOW_HMAC_SECRET;
const baseUrl = $env.APP_BASE_URL;
if (!secret || !baseUrl) throw new Error('Recovery poll environment is not configured');
const signature = `sha256=${crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex')}`;
return [{ json: { body, nonce, signature, timestamp, url: `${baseUrl}${path}` } }];
